// Package: AWSSDK.ApiGateway
using Amazon.ApiGatewayManagement;
using Amazon.APIGateway;
using Amazon.APIGateway.Model;

var apiClient = new AmazonAPIGatewayClient(RegionEndpoint.USEast1);

var createApiRequest = new CreateRestApiRequest
{
    Name = "aspnet-orders-api",
    Description = "Serverless orders API"
};
var createApiResponse = await apiClient.CreateRestApiAsync(createApiRequest);
string restApiId = createApiResponse.Id;
Console.WriteLine($"API ID: {restApiId}");

var createResourceRequest = new CreateResourceRequest
{
    RestApiId = restApiId,
    ParentId = (await apiClient.GetRootResourcesAsync(new GetResourcesRequest
    {
        RestApiId = restApiId
    })).Items[0].Id,
    PathPart = "orders",
    Name = "Orders"
};
var resourceResponse = await apiClient.CreateResourceAsync(createResourceRequest);
string resourceId = resourceResponse.Id;

var putMethodRequest = new PutMethodRequest
{
    RestApiId = restApiId,
    ResourceId = resourceId,
    HttpMethod = HttpMethod.GET,
    AuthorizationType = "NONE"
};
await apiClient.PutMethodAsync(putMethodRequest);

var integrationRequest = new PutIntegrationRequest
{
    RestApiId = restApiId,
    ResourceId = resourceId,
    HttpMethod = HttpMethod.GET,
    Type = IntegrationType.AWS,
    IntegrationHttpMethod = HttpMethod.POST,
    Uri = $"arn:aws:apigateway:us-east-1:lambda:path/2015-03-31/functions/arn:aws:lambda:us-east-1:123456789012:function:aspnet-process-order/invocations"
};
await apiClient.PutIntegrationAsync(integrationRequest);

// Package: AWSSDK.Lambda
// Install Amazon.Lambda.APIGatewayEvents
using Amazon.Lambda.APIGatewayEvents;
using Amazon.Lambda.Core;

[assembly: LambdaSerializer(typeof(Amazon.Lambda.Serialization.Json.JsonSerializer))]

public class Function
{
    public APIGatewayProxyResponse FunctionHandler(
        APIGatewayProxyRequest request,
        ILambdaContext context)
    {
        context.Logger.LogLine($"Received {request.HttpMethod} {request.Path}");

        string orderId = request.PathParameters?["orderId"] ?? string.Empty;
        var order = new { Id = orderId, Total = 59.99m, Status = "Shipped" };

        return new APIGatewayProxyResponse
        {
            StatusCode = 200,
            Body = System.Text.Json.JsonSerializer.Serialize(order),
            Headers = new Dictionary<string, string>
            {
                ["Content-Type"] = "application/json"
            }
        };
    }
}
